def is_good_triple(x, y, z):
    """
    Checks if the triple (x, y, z) is a good triple.
    A triple is good if (x+1)^y / (x^z + 1) is a positive integer.
    """
    # Check the constraint derived by W3: if x is even, z must be odd.
    if x % 2 == 0 and z % 2 == 0:
        return False

    # Since x, y, z >= 1, x+1 >= 2 and x^z + 1 >= 2.
    # We check for divisibility: (x+1)^y % (x^z + 1) == 0

    try:
        numerator = (x + 1)**y
        denominator = x**z + 1
    except OverflowError:
        # Should not happen with Python's arbitrary precision integers,
        # but good practice to acknowledge the theoretical risk.
        return False

    return numerator % denominator == 0

def count_good_triples(limit=99):
    count = 0
    for x in range(1, limit + 1):
